// Logo mitra RRI untuk strip marquee landing page — PUTIH di atas navy
// (PR landing-logo-mitra-tanpa-box, 2026-11-18; mengolah ulang PR #101).
//
// Sumber: 10 file logo yang DIUNGGAH PENGGUNA (bukan unduhan web), di-embed
// sebagai data URI base64 karena push snapshot GitHub hanya menerima file
// teks (pola yang sama seperti logoDeals.ts / logoRriLanding.ts).
//   Taspen: Taspen.jpeg (FOTO kantor — logo di-crop dari dinding, tanpa
//     tagline "Andal Melayani"); Bank Sumsel Babel: Logo_Bank_Sumsel_Babel.tif.png;
//   PLN: Logo_PLN.svg.webp; Alfamart: ALFAMART_LOGO_BARU.png;
//   MedcoEnergi: Logo_MedcoEnergi.png; Bea Cukai: Logo_Bea_Cukai.bin (PNG);
//   Bank Indonesia: lg-65f95ef3cd696-BANK-INDONESIA.webp (BUKAN foto gedung
//     Bank_Indonesia.webp); BNN: Logo_BNN.png; DJP: images.png;
//   Komdigi: Logo_Kementerian_Komunikasi_dan_Digital_Republik_Indonesia__2024_.svg.webp
//     (teks "KOMDIGI" lengkap; image.png terpotong di kedua sisi).
//
// Pemrosesan (PIL, dari file asli): tiap logo diolah menjadi
// PUTIH-TRANSPARAN — piksel putih/latar -> transparan, bagian
// berwarna/gelap -> putih (alpha dari 255 - min(r,g,b), digabung dengan
// alpha asli), lalu THRESHOLD 100 (latar jadi 0, artwork jadi 255),
// lubang artefak (highlight foto, mean alpha > 65) diisi, trim ke isi
// logo (bbox alpha > 8), resize ke tinggi 96px (tampil h-10 = 40px,
// ~2.4x untuk layar retina), threshold ulang 100, feather tepi 0.7px,
// padding transparan 2px, WebP q85.
// Alasan olah ulang: konversi PR #101 menyisakan KABUT putih
// semi-transparan di seluruh frame persegi (BNN 75% piksel semi,
// Komdigi 24% semi, kesepuluh logo 20-75% semi) — di atas navy kabut itu
// terbaca sebagai kotak/bar persegi di balik tiap logo (laporan pengguna
// 2026-11-18, screenshot BNN + Komdigi). Versi ini: sudut + tepi frame
// alpha 0, kabut latar 0, semi-transparan HANYA di pita feather <=2px.
// JANGAN pakai filter CSS brightness(0) invert(1): cara itu SUDAH DIUJI
// di PR #97 dan GAGAL — BNN jadi lingkaran putih polos dan PLN jadi kotak
// putih, karena kedua logo itu berlatar opak (siluet = bentuk alpha-nya saja).
// Perlakuan khusus:
// - PLN: kotak kuning DIBUANG (piksel kuning -> transparan); petir merah
//   + gelombang biru dipertahankan sebagai line-art putih.
// - BNN: teks putih di cincin jadi transparan (knockout, terbaca navy di
//   atas cincin putih); teks "BNN" hitam juga di-knockout supaya tetap
//   terbaca; Garuda di tengah menyatu ke cakram putih (detail hilang —
//   lencana tetap terbaca sebagai lencana, bukan lingkaran polos).
// - Bea Cukai: detail hitam di dalam pentagon jadi putih; gelombang putih
//   di dalamnya jadi knockout (garis navy di atas pentagon putih).
// - Komdigi: teks "KOMDIGI" kini putih pekat (di PR #101 masih redup,
//   alpha menengah) — sumber .webp teksnya lengkap.
// Di Marklo.tsx logo tampil LANGSUNG di atas latar navy (tanpa chip putih
// sejak PR #101); fade tepi marquee (PR #98) tetap.
//
// Logo dipakai apa adanya, tidak diwarnai ulang — ini versi putih resmi
// dari file yang sama, seperti wordmark putih template di latar gelap.

export interface LogoMitra {
  /** Nama mitra — dipakai sebagai alt text dan label aksesibilitas. */
  nama: string;
  /** Data URI lengkap hasil embed (PNG/WebP base64). */
  logoDataUri: string;
}

